// ---------------------------------------------------------------------------
// ASYNC
// --- returns error msg if any, else ''

export const typeCheckTsFile = async (
		path: string
		): AutoPromise<string> => {

	const {success, stderr} = await execCmd('deno', [
		"check",
		'--quiet',
		path
		])
	if (success) {
		return ''
	}
	else {
		return stderr || `Type Check failed for ${path}`
	}
}

// ---------------------------------------------------------------------------
// ASYNC
// --- returns err msg or ''

export const typeCheckTsCode = async (
		tsCode: string
		): AutoPromise<string> => {

	const tsPath = await mkTempFile('.ts')
	await Deno.writeTextFile(tsPath, tsCode)
	return await typeCheckTsFile(tsPath)
}

// ---------------------------------------------------------------------------

export const ts2ast = (
		tsCode: string,
		hOptions: hash = {}
		): SourceFile => {

	type opt = {
		fileName: string
		}
	const {fileName} = getOptions<opt>(hOptions, {
		fileName: 'temp.ts'
		})

	const [code, hSrcMap] = extractSourceMap(tsCode)
	return createSourceFile(fileName, code, ScriptTarget.Latest)
}

// ---------------------------------------------------------------------------

export const kindStr = (i: number): string => {

	return SyntaxKind[i]
}

// ---------------------------------------------------------------------------

export const ast2ts = (
		node: Node
		): string => {

	assert((node.kind === 308), "Not a SourceFile node")
	const printer = createPrinter({newLine: NewLineKind.LineFeed})
	return printer.printNode(EmitHint.Unspecified, node, node as SourceFile)
}

// ---------------------------------------------------------------------------
// --- passed to nice() to add a description to some nodes

export const descFunc: TDescFunc = (
		key: string,
		value: unknown,
		hParent: unknown
		): string => {

	return (key === 'kind') && isNumber(value) ? f`(${kindStr(value)})` : ''
}

// ---------------------------------------------------------------------------

export const astAsString = (
		hAst: object,
		hOptions: hash = {}
		): string => {

	return ML(hAst, {
		ignoreEmptyKeys: true,
		lExclude: words(`pos end id flags modifierFlagsCache
transformFlags hasExtendedUnicodeEscape
numericLiteralFlags setExternalModuleIndicator
languageVersion languageVariant jsDocParsingMode
hasNoDefaultLib`)
		})
}

